-- Schema extension. The v2 serial grain carries five columns the original
-- sql/15 shape has no home for, and they are the columns that make the
-- component view worth looking at -- the real component name, and whether a
-- component was ATTRIBUTED the incident or merely EXPOSED to it.
ALTER TABLE ps3_serial_predictions ADD COLUMN IF NOT EXISTS component_description  VARCHAR(120);
ALTER TABLE ps3_serial_predictions ADD COLUMN IF NOT EXISTS attribution_basis      VARCHAR(24);
ALTER TABLE ps3_serial_predictions ADD COLUMN IF NOT EXISTS n_incidents_exposed    INT;
ALTER TABLE ps3_serial_predictions ADD COLUMN IF NOT EXISTS n_incidents_attributed INT;
ALTER TABLE ps3_serial_predictions ADD COLUMN IF NOT EXISTS pct_critical_exposed   NUMERIC(7,4);
ALTER TABLE ps3_serial_predictions ADD COLUMN IF NOT EXISTS pct_critical_attributed NUMERIC(7,4);
CREATE INDEX IF NOT EXISTS idx_ps3_ser_component
  ON ps3_serial_predictions (city_id, component_description);

-- Idempotent: re-running replaces this run, never duplicates it.
